#[test_only]
public struct DummyMarket {}

#[test_only]
fun set_borrow_index<MarketType>(self: &mut Reserve<MarketType>, value: Decimal, now: u64) {
    self.borrow_index.set_value(value, now);
}

#[test_only]
fun ensure_invariants_hold<MarketType, CoinType>(self: &Reserve<MarketType>,) {
    assert!(self.cash >= self.cash_reserve.floor());

    let reserve_token_balance: &ReserveBalance<MarketType, CoinType> = dynamic_field::borrow(&self.id, ReserveBalanceKey{});

    assert!(self.cash == reserve_token_balance.underlying_balance.value());
    assert!(self.total_supply >= reserve_token_balance.ctoken_supply.supply_value());
}

#[test]
fun test_reserve_mint_then_burn_works() {
    let admin = @0xAD;
    let mut scenario_value = sui::test_scenario::begin(admin);

    let ctx = scenario_value.ctx();

    let mut reserve = new<MainMarket, BTC>(ctx, 1);

    let amount = 1000;
    let btc = sui::balance::create_for_testing<BTC>(amount).into_coin(ctx);

    let ctokens = reserve.mint_ctokens<MainMarket, BTC>(btc).into_coin(ctx);
    assert!(ctokens.value() == amount);

    assert!(reserve.util_rate() == float::from_quotient(0, 1));
    assert!(reserve.exchange_rate() == math::float::from_quotient(1, 1));

    let btc = reserve.burn_ctokens<MainMarket, BTC>(ctokens);
    assert!(btc.value() == amount);

    sui::balance::destroy_for_testing(btc);
    std::unit_test::destroy(reserve);
    scenario_value.end();
}

/// Supply 1000 BTC, borrow 100 BTC, utilization rate = 100 / 900, exchange rate = 900 / 1000
#[test]
fun test_reserve_basic_lifecycle_works() {
    let admin = @0xAD;
    let mut scenario_value = sui::test_scenario::begin(admin);

    let ctx = scenario_value.ctx();
    let mut reserve = new<MainMarket, BTC>(ctx, 1);

    let amount = 1000;
    let btc = sui::balance::create_for_testing<BTC>(amount).into_coin(ctx);
    let mut ctokens = reserve.mint_ctokens<MainMarket, BTC>(btc).into_coin(ctx);
    reserve.ensure_invariants_hold<MainMarket, BTC>();

    let mut borrowed_balance = reserve.borrow_amount<MainMarket, BTC>(100);
